SELECT SUM(Total) FROM body_builder WHERE People_ID IN (
  SELECT People_ID FROM people WHERE Birth_Date LIKE '%January%'
)

SELECT Project_ID, Project_Details FROM Projects WHERE Project_ID IN (
    SELECT Project_ID FROM Documents GROUP BY Project_ID HAVING COUNT(*) >= 2
)

SELECT DISTINCT name FROM useracct WHERE u_id NOT IN (
  SELECT u_id FROM review
)
